using System;using System.IO;
namespace SarmatVisionHold.Infrastructure { public sealed class VisionHoldLog:IDisposable { readonly object gate=new object();readonly StreamWriter writer;public VisionHoldLog(string path){Directory.CreateDirectory(Path.GetDirectoryName(path));writer=new StreamWriter(new FileStream(path,FileMode.Append,FileAccess.Write,FileShare.ReadWrite)){AutoFlush=true};}public void Info(string m){lock(gate)writer.WriteLine($"{DateTime.UtcNow:O} INFO {m}");}public void Error(string m,Exception e){lock(gate)writer.WriteLine($"{DateTime.UtcNow:O} ERROR {m}: {e}");}public void Dispose(){lock(gate)writer.Dispose();} } }
